# 7-matematik-14 görsel modülü

GORSELLER = {'b1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSTATİSTİKSEL ARAŞTIRMA SÜRECİ VE VERİ TÜRLERİ (MAT.7.6.1)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Kategorik (Nitel) Veri</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Sayısal ölçüm belirtmeyen; isim, grup, tür</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  veya nitelik bildiren verilerdir.</text>\n  <text x="40" y="140" font-size="11" fill="#334155">• Örnekler: Sevilen kitap türleri, kan grupları,</text>\n  <text x="40" y="158" font-size="11" fill="#334155">  tercih edilen spor dalları, göz renkleri.</text>\n  <text x="40" y="184" font-size="11" font-weight="bold" fill="#1e40af">• Uygun Grafikler: Sütun Grafiği ve Daire Grafiği</text>\n  <text x="40" y="206" font-size="11" fill="#334155">• Özetleme: Tepe Değer (Mod / En çok tekrar eden)</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Nicel (Kesikli ve Sürekli) Veri</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Sayma veya ölçme yoluyla elde edilen sayısal</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  verilerdir (Aralıktaki her değeri alabiliyorsa sürekli).</text>\n  <text x="375" y="140" font-size="11" fill="#334155">• Örnekler: Boy uzunluğu (cm), kütle (kg), hava</text>\n  <text x="375" y="158" font-size="11" fill="#334155">  sıcaklığı (°C), koşu süresi (sn), okunan sayfa sayısı.</text>\n  <text x="375" y="184" font-size="11" font-weight="bold" fill="#166534">• Uygun Grafikler: Nokta, Çizgi ve Sütun Grafiği</text>\n  <text x="375" y="206" font-size="11" fill="#334155">• Özetleme: Ortalama, Ortanca, Açıklık, OMS</text>\n</svg>', '1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSTATİSTİKSEL ARAŞTIRMA SÜRECİ VE VERİ TÜRLERİ (MAT.7.6.1)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Kategorik (Nitel) Veri</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Sayısal ölçüm belirtmeyen; isim, grup, tür</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  veya nitelik bildiren verilerdir.</text>\n  <text x="40" y="140" font-size="11" fill="#334155">• Örnekler: Sevilen kitap türleri, kan grupları,</text>\n  <text x="40" y="158" font-size="11" fill="#334155">  tercih edilen spor dalları, göz renkleri.</text>\n  <text x="40" y="184" font-size="11" font-weight="bold" fill="#1e40af">• Uygun Grafikler: Sütun Grafiği ve Daire Grafiği</text>\n  <text x="40" y="206" font-size="11" fill="#334155">• Özetleme: Tepe Değer (Mod / En çok tekrar eden)</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Nicel (Kesikli ve Sürekli) Veri</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Sayma veya ölçme yoluyla elde edilen sayısal</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  verilerdir (Aralıktaki her değeri alabiliyorsa sürekli).</text>\n  <text x="375" y="140" font-size="11" fill="#334155">• Örnekler: Boy uzunluğu (cm), kütle (kg), hava</text>\n  <text x="375" y="158" font-size="11" fill="#334155">  sıcaklığı (°C), koşu süresi (sn), okunan sayfa sayısı.</text>\n  <text x="375" y="184" font-size="11" font-weight="bold" fill="#166534">• Uygun Grafikler: Nokta, Çizgi ve Sütun Grafiği</text>\n  <text x="375" y="206" font-size="11" fill="#334155">• Özetleme: Ortalama, Ortanca, Açıklık, OMS</text>\n</svg>', 'b2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">NOKTA GRAFİĞİ VE ÇİZGİ GRAFİĞİ İLE DAĞILIM ANALİZİ</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Nokta Grafiği (Yığılma ve Uç Değer)</text>\n  <line x1="50" y1="190" x2="310" y2="190" stroke="#1e293b" stroke-width="2"/>\n  <text x="70" y="208" text-anchor="middle" font-size="10.5" fill="#334155">1</text>\n  <text x="115" y="208" text-anchor="middle" font-size="10.5" fill="#334155">2</text>\n  <text x="160" y="208" text-anchor="middle" font-size="10.5" fill="#334155">3</text>\n  <text x="205" y="208" text-anchor="middle" font-size="10.5" fill="#334155">4</text>\n  <text x="290" y="208" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">9 (Uç)</text>\n  <circle cx="70" cy="175" r="5" fill="#2563eb"/>\n  <circle cx="115" cy="175" r="5" fill="#2563eb"/>\n  <circle cx="115" cy="160" r="5" fill="#2563eb"/>\n  <circle cx="115" cy="145" r="5" fill="#2563eb"/>\n  <circle cx="160" cy="175" r="5" fill="#2563eb"/>\n  <circle cx="160" cy="160" r="5" fill="#2563eb"/>\n  <circle cx="205" cy="175" r="5" fill="#2563eb"/>\n  <circle cx="290" cy="175" r="5" fill="#ef4444"/>\n  <text x="182" y="105" text-anchor="middle" font-size="10.5" fill="#1e40af">Tepe Değer (Mod) = 2 (En çok nokta olan değer)</text>\n  <text x="182" y="228" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">9 değeri diğerlerinden uzak UÇ (AYKIRI) değerdir</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Çizgi Grafiği (Zamana Bağlı Sürekli Değişim)</text>\n  <line x1="395" y1="190" x2="650" y2="190" stroke="#1e293b" stroke-width="2"/>\n  <line x1="395" y1="90" x2="395" y2="190" stroke="#1e293b" stroke-width="2"/>\n  <polyline points="415,170 465,135 515,135 565,105 615,150" fill="none" stroke="#ca8a04" stroke-width="3"/>\n  <circle cx="415" cy="170" r="4" fill="#a16207"/>\n  <circle cx="465" cy="135" r="4" fill="#a16207"/>\n  <circle cx="515" cy="135" r="4" fill="#a16207"/>\n  <circle cx="565" cy="105" r="4" fill="#a16207"/>\n  <circle cx="615" cy="150" r="4" fill="#a16207"/>\n  <text x="415" y="208" text-anchor="middle" font-size="10" fill="#334155">1. Gün</text>\n  <text x="465" y="208" text-anchor="middle" font-size="10" fill="#334155">2. Gün</text>\n  <text x="515" y="208" text-anchor="middle" font-size="10" fill="#334155">3. Gün</text>\n  <text x="565" y="208" text-anchor="middle" font-size="10" fill="#334155">4. Gün</text>\n  <text x="615" y="208" text-anchor="middle" font-size="10" fill="#334155">5. Gün</text>\n  <text x="517" y="228" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">2-3. Gün Sabit | En Yüksek: 4. Gün | En Düşük: 1. Gün</text>\n</svg>', '2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">NOKTA GRAFİĞİ VE ÇİZGİ GRAFİĞİ İLE DAĞILIM ANALİZİ</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Nokta Grafiği (Yığılma ve Uç Değer)</text>\n  <line x1="50" y1="190" x2="310" y2="190" stroke="#1e293b" stroke-width="2"/>\n  <text x="70" y="208" text-anchor="middle" font-size="10.5" fill="#334155">1</text>\n  <text x="115" y="208" text-anchor="middle" font-size="10.5" fill="#334155">2</text>\n  <text x="160" y="208" text-anchor="middle" font-size="10.5" fill="#334155">3</text>\n  <text x="205" y="208" text-anchor="middle" font-size="10.5" fill="#334155">4</text>\n  <text x="290" y="208" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">9 (Uç)</text>\n  <circle cx="70" cy="175" r="5" fill="#2563eb"/>\n  <circle cx="115" cy="175" r="5" fill="#2563eb"/>\n  <circle cx="115" cy="160" r="5" fill="#2563eb"/>\n  <circle cx="115" cy="145" r="5" fill="#2563eb"/>\n  <circle cx="160" cy="175" r="5" fill="#2563eb"/>\n  <circle cx="160" cy="160" r="5" fill="#2563eb"/>\n  <circle cx="205" cy="175" r="5" fill="#2563eb"/>\n  <circle cx="290" cy="175" r="5" fill="#ef4444"/>\n  <text x="182" y="105" text-anchor="middle" font-size="10.5" fill="#1e40af">Tepe Değer (Mod) = 2 (En çok nokta olan değer)</text>\n  <text x="182" y="228" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">9 değeri diğerlerinden uzak UÇ (AYKIRI) değerdir</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Çizgi Grafiği (Zamana Bağlı Sürekli Değişim)</text>\n  <line x1="395" y1="190" x2="650" y2="190" stroke="#1e293b" stroke-width="2"/>\n  <line x1="395" y1="90" x2="395" y2="190" stroke="#1e293b" stroke-width="2"/>\n  <polyline points="415,170 465,135 515,135 565,105 615,150" fill="none" stroke="#ca8a04" stroke-width="3"/>\n  <circle cx="415" cy="170" r="4" fill="#a16207"/>\n  <circle cx="465" cy="135" r="4" fill="#a16207"/>\n  <circle cx="515" cy="135" r="4" fill="#a16207"/>\n  <circle cx="565" cy="105" r="4" fill="#a16207"/>\n  <circle cx="615" cy="150" r="4" fill="#a16207"/>\n  <text x="415" y="208" text-anchor="middle" font-size="10" fill="#334155">1. Gün</text>\n  <text x="465" y="208" text-anchor="middle" font-size="10" fill="#334155">2. Gün</text>\n  <text x="515" y="208" text-anchor="middle" font-size="10" fill="#334155">3. Gün</text>\n  <text x="565" y="208" text-anchor="middle" font-size="10" fill="#334155">4. Gün</text>\n  <text x="615" y="208" text-anchor="middle" font-size="10" fill="#334155">5. Gün</text>\n  <text x="517" y="228" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">2-3. Gün Sabit | En Yüksek: 4. Gün | En Düşük: 1. Gün</text>\n</svg>', 'b3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÜTUN VE DAİRE GRAFİĞİ DÖNÜŞÜMLERİ (MERKEZ AÇI)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="182" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Sütun Grafiği (Kategorik Karşılaştırma)</text>\n  <line x1="60" y1="195" x2="300" y2="195" stroke="#1e293b" stroke-width="2"/>\n  <rect x="80" y="115" width="40" height="80" fill="#3b82f6"/>\n  <text x="100" y="108" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">40</text>\n  <text x="100" y="212" text-anchor="middle" font-size="10.5" fill="#334155">A Grubu</text>\n  <rect x="155" y="135" width="40" height="60" fill="#22c55e"/>\n  <text x="175" y="128" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">30</text>\n  <text x="175" y="212" text-anchor="middle" font-size="10.5" fill="#334155">B Grubu</text>\n  <rect x="230" y="155" width="40" height="40" fill="#eab308"/>\n  <text x="250" y="148" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#a16207">20</text>\n  <text x="250" y="212" text-anchor="middle" font-size="10.5" fill="#334155">C Grubu</text>\n  <text x="182" y="230" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Toplam Veri = 40 + 30 + 20 = 90 Kişi</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="517" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Daire Grafiğine Dönüşüm (360° / 90 = 4°)</text>\n  <circle cx="435" cy="145" r="52" fill="#3b82f6" stroke="#1e293b" stroke-width="1.5"/>\n  <path d="M 435 145 L 435 93 A 52 52 0 0 1 480 171 Z" fill="#22c55e"/>\n  <path d="M 435 145 L 480 171 A 52 52 0 0 1 417 194 Z" fill="#eab308"/>\n  <text x="505" y="108" font-size="11" fill="#334155">• 1 Kişi = 360° ÷ 90 = 4°</text>\n  <text x="505" y="132" font-size="11" font-weight="bold" fill="#1d4ed8">• A (40 kişi): 40 × 4° = 160°</text>\n  <text x="505" y="156" font-size="11" font-weight="bold" fill="#15803d">• B (30 kişi): 30 × 4° = 120°</text>\n  <text x="505" y="180" font-size="11" font-weight="bold" fill="#a16207">• C (20 kişi): 20 × 4° = 80°</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Toplam Merkez Açı: 160° + 120° + 80° = 360°</text>\n</svg>', '3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÜTUN VE DAİRE GRAFİĞİ DÖNÜŞÜMLERİ (MERKEZ AÇI)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="182" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Sütun Grafiği (Kategorik Karşılaştırma)</text>\n  <line x1="60" y1="195" x2="300" y2="195" stroke="#1e293b" stroke-width="2"/>\n  <rect x="80" y="115" width="40" height="80" fill="#3b82f6"/>\n  <text x="100" y="108" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">40</text>\n  <text x="100" y="212" text-anchor="middle" font-size="10.5" fill="#334155">A Grubu</text>\n  <rect x="155" y="135" width="40" height="60" fill="#22c55e"/>\n  <text x="175" y="128" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">30</text>\n  <text x="175" y="212" text-anchor="middle" font-size="10.5" fill="#334155">B Grubu</text>\n  <rect x="230" y="155" width="40" height="40" fill="#eab308"/>\n  <text x="250" y="148" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#a16207">20</text>\n  <text x="250" y="212" text-anchor="middle" font-size="10.5" fill="#334155">C Grubu</text>\n  <text x="182" y="230" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Toplam Veri = 40 + 30 + 20 = 90 Kişi</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="517" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Daire Grafiğine Dönüşüm (360° / 90 = 4°)</text>\n  <circle cx="435" cy="145" r="52" fill="#3b82f6" stroke="#1e293b" stroke-width="1.5"/>\n  <path d="M 435 145 L 435 93 A 52 52 0 0 1 480 171 Z" fill="#22c55e"/>\n  <path d="M 435 145 L 480 171 A 52 52 0 0 1 417 194 Z" fill="#eab308"/>\n  <text x="505" y="108" font-size="11" fill="#334155">• 1 Kişi = 360° ÷ 90 = 4°</text>\n  <text x="505" y="132" font-size="11" font-weight="bold" fill="#1d4ed8">• A (40 kişi): 40 × 4° = 160°</text>\n  <text x="505" y="156" font-size="11" font-weight="bold" fill="#15803d">• B (30 kişi): 30 × 4° = 120°</text>\n  <text x="505" y="180" font-size="11" font-weight="bold" fill="#a16207">• C (20 kişi): 20 × 4° = 80°</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Toplam Merkez Açı: 160° + 120° + 80° = 360°</text>\n</svg>', 'b4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MERKEZİ EĞİLİM ÖLÇÜLERİ: ORTALAMA, ORTANCA VE TEPE DEĞER</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Aritmetik Ortalama</text>\n  <text x="35" y="98" font-size="11" fill="#334155">• Verilerin toplamının veri</text>\n  <text x="35" y="116" font-size="11" fill="#334155">  adedine bölümüdür.</text>\n  <text x="35" y="142" font-size="11" fill="#334155">• Uç (aykırı) değerlerden</text>\n  <text x="35" y="160" font-size="11" font-weight="bold" fill="#b91c1c">  çok etkilenir!</text>\n  <text x="35" y="186" font-size="10.5" fill="#1e40af">• Uç değer yoksa grubu en</text>\n  <text x="35" y="204" font-size="10.5" fill="#1e40af">  iyi temsil eden ölçüdür.</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Ortanca (Medyan)</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Küçükten büyüğe sıralanan</text>\n  <text x="260" y="116" font-size="11" fill="#334155">  verilerin tam ortasındaki sayıdır.</text>\n  <text x="260" y="142" font-size="11" fill="#334155">• Çift sayıda veri varsa ortadaki</text>\n  <text x="260" y="160" font-size="11" fill="#334155">  iki sayının ortalaması alınır.</text>\n  <text x="260" y="186" font-size="10.5" font-weight="bold" fill="#166534">• Uç (aykırı) değer varsa</text>\n  <text x="260" y="204" font-size="10.5" font-weight="bold" fill="#166534">  en uygun temsilcidir!</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Tepe Değer (Mod)</text>\n  <text x="485" y="98" font-size="11" fill="#334155">• Veri grubunda en çok tekrar</text>\n  <text x="485" y="116" font-size="11" fill="#334155">  eden (frekansı en yüksek) değerdir.</text>\n  <text x="485" y="142" font-size="11" fill="#334155">• Tüm veriler eşit sayıda ise</text>\n  <text x="485" y="160" font-size="11" fill="#334155">  tepe değer yoktur; birden</text>\n  <text x="485" y="178" font-size="11" fill="#334155">  fazla tepe değer olabilir.</text>\n  <text x="485" y="204" font-size="10.5" font-weight="bold" fill="#92400e">• En popüler tercihi gösterir.</text>\n</svg>', '4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MERKEZİ EĞİLİM ÖLÇÜLERİ: ORTALAMA, ORTANCA VE TEPE DEĞER</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Aritmetik Ortalama</text>\n  <text x="35" y="98" font-size="11" fill="#334155">• Verilerin toplamının veri</text>\n  <text x="35" y="116" font-size="11" fill="#334155">  adedine bölümüdür.</text>\n  <text x="35" y="142" font-size="11" fill="#334155">• Uç (aykırı) değerlerden</text>\n  <text x="35" y="160" font-size="11" font-weight="bold" fill="#b91c1c">  çok etkilenir!</text>\n  <text x="35" y="186" font-size="10.5" fill="#1e40af">• Uç değer yoksa grubu en</text>\n  <text x="35" y="204" font-size="10.5" fill="#1e40af">  iyi temsil eden ölçüdür.</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Ortanca (Medyan)</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Küçükten büyüğe sıralanan</text>\n  <text x="260" y="116" font-size="11" fill="#334155">  verilerin tam ortasındaki sayıdır.</text>\n  <text x="260" y="142" font-size="11" fill="#334155">• Çift sayıda veri varsa ortadaki</text>\n  <text x="260" y="160" font-size="11" fill="#334155">  iki sayının ortalaması alınır.</text>\n  <text x="260" y="186" font-size="10.5" font-weight="bold" fill="#166534">• Uç (aykırı) değer varsa</text>\n  <text x="260" y="204" font-size="10.5" font-weight="bold" fill="#166534">  en uygun temsilcidir!</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Tepe Değer (Mod)</text>\n  <text x="485" y="98" font-size="11" fill="#334155">• Veri grubunda en çok tekrar</text>\n  <text x="485" y="116" font-size="11" fill="#334155">  eden (frekansı en yüksek) değerdir.</text>\n  <text x="485" y="142" font-size="11" fill="#334155">• Tüm veriler eşit sayıda ise</text>\n  <text x="485" y="160" font-size="11" fill="#334155">  tepe değer yoktur; birden</text>\n  <text x="485" y="178" font-size="11" fill="#334155">  fazla tepe değer olabilir.</text>\n  <text x="485" y="204" font-size="10.5" font-weight="bold" fill="#92400e">• En popüler tercihi gösterir.</text>\n</svg>', 'b5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YAYILIM ÖLÇÜLERİ: AÇIKLIK VE ORTALAMA MUTLAK SAPMA (OMS)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Ortalama Mutlak Sapma (OMS) Adımları</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• 1. Adım: Veri grubunun aritmetik ortalaması bulunur.</text>\n  <text x="40" y="122" font-size="11" fill="#334155">• 2. Adım: Her bir verinin aritmetik ortalamaya olan</text>\n  <text x="40" y="140" font-size="11" fill="#334155">  uzaklığı (pozitif / mutlak farkı) tek tek hesaplanır.</text>\n  <text x="40" y="164" font-size="11" fill="#334155">• 3. Adım: Bulunan bu uzaklıklar toplanır ve</text>\n  <text x="40" y="182" font-size="11" fill="#334155">  toplam veri sayısına bölünür.</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Açıklık = En Büyük Değer - En Küçük Değer</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Örnek OMS Hesabı: Veriler (4, 6, 8, 10, 12)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• 1) Ortalama = (4 + 6 + 8 + 10 + 12) ÷ 5 = 40 ÷ 5 = 8</text>\n  <text x="375" y="122" font-size="11" fill="#334155">• 2) Ortalamaya (8\'e) uzaklıklar:</text>\n  <text x="375" y="142" font-size="11" fill="#334155">     |4-8|=4, |6-8|=2, |8-8|=0, |10-8|=2, |12-8|=4</text>\n  <text x="375" y="166" font-size="11" fill="#334155">• 3) Uzaklıklar toplamı = 4 + 2 + 0 + 2 + 4 = 12</text>\n  <text x="375" y="190" font-size="11" font-weight="bold" fill="#9d174d">• OMS = 12 ÷ 5 = 2,4   |   Açıklık = 12 - 4 = 8</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">OMS Küçüldükçe Veriler Ortalamaya Yakınlaşır</text>\n</svg>', '5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YAYILIM ÖLÇÜLERİ: AÇIKLIK VE ORTALAMA MUTLAK SAPMA (OMS)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Ortalama Mutlak Sapma (OMS) Adımları</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• 1. Adım: Veri grubunun aritmetik ortalaması bulunur.</text>\n  <text x="40" y="122" font-size="11" fill="#334155">• 2. Adım: Her bir verinin aritmetik ortalamaya olan</text>\n  <text x="40" y="140" font-size="11" fill="#334155">  uzaklığı (pozitif / mutlak farkı) tek tek hesaplanır.</text>\n  <text x="40" y="164" font-size="11" fill="#334155">• 3. Adım: Bulunan bu uzaklıklar toplanır ve</text>\n  <text x="40" y="182" font-size="11" fill="#334155">  toplam veri sayısına bölünür.</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Açıklık = En Büyük Değer - En Küçük Değer</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Örnek OMS Hesabı: Veriler (4, 6, 8, 10, 12)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• 1) Ortalama = (4 + 6 + 8 + 10 + 12) ÷ 5 = 40 ÷ 5 = 8</text>\n  <text x="375" y="122" font-size="11" fill="#334155">• 2) Ortalamaya (8\'e) uzaklıklar:</text>\n  <text x="375" y="142" font-size="11" fill="#334155">     |4-8|=4, |6-8|=2, |8-8|=0, |10-8|=2, |12-8|=4</text>\n  <text x="375" y="166" font-size="11" fill="#334155">• 3) Uzaklıklar toplamı = 4 + 2 + 0 + 2 + 4 = 12</text>\n  <text x="375" y="190" font-size="11" font-weight="bold" fill="#9d174d">• OMS = 12 ÷ 5 = 2,4   |   Açıklık = 12 - 4 = 8</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">OMS Küçüldükçe Veriler Ortalamaya Yakınlaşır</text>\n</svg>', 'b6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İKİ VERİ GRUBUNU KARŞILAŞTIRMA VE VERİYE DAYALI KARAR</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Tutarlılık ve İstikrar Karşılaştırması</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• X Grubu: 18, 19, 20, 21, 22 -&gt; Ort = 20, OMS = 1,2</text>\n  <text x="40" y="122" font-size="11" fill="#334155">• Y Grubu: 10, 15, 20, 25, 30 -&gt; Ort = 20, OMS = 6,0</text>\n  <text x="40" y="148" font-size="11" font-weight="bold" fill="#166534">• Yorum: İki grubun aritmetik ortalaması eşit (20)</text>\n  <text x="40" y="166" font-size="11" font-weight="bold" fill="#166534">  olsa da X grubunun OMS ve açıklığı daha küçüktür.</text>\n  <text x="40" y="190" font-size="11" fill="#334155">• Karar: X grubu daha istikrarlı (tutarlı / homojen),</text>\n  <text x="40" y="208" font-size="11" fill="#334155">  Y grubu ise daha değişken (heterojen) yapıdadır.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Araştırma Sürecini Yeniden Planlama (MAT.7.6.1.g)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Örneklem çok küçükse (örn. yalnız 3 kişiye sorulduysa)</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  örneklem genişletilir.</text>\n  <text x="375" y="140" font-size="11" fill="#334155">• Örneklem yanlı seçildiyse (örn. okulun en sevilen</text>\n  <text x="375" y="158" font-size="11" fill="#334155">  sporu için yalnız futbol takımına sorulduysa) tüm</text>\n  <text x="375" y="176" font-size="11" fill="#334155">  şubelerden rastgele örneklem seçilir.</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Tarafsız ve Yeterli Örneklem = Doğru Karar</text>\n</svg>', '6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İKİ VERİ GRUBUNU KARŞILAŞTIRMA VE VERİYE DAYALI KARAR</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Tutarlılık ve İstikrar Karşılaştırması</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• X Grubu: 18, 19, 20, 21, 22 -&gt; Ort = 20, OMS = 1,2</text>\n  <text x="40" y="122" font-size="11" fill="#334155">• Y Grubu: 10, 15, 20, 25, 30 -&gt; Ort = 20, OMS = 6,0</text>\n  <text x="40" y="148" font-size="11" font-weight="bold" fill="#166534">• Yorum: İki grubun aritmetik ortalaması eşit (20)</text>\n  <text x="40" y="166" font-size="11" font-weight="bold" fill="#166534">  olsa da X grubunun OMS ve açıklığı daha küçüktür.</text>\n  <text x="40" y="190" font-size="11" fill="#334155">• Karar: X grubu daha istikrarlı (tutarlı / homojen),</text>\n  <text x="40" y="208" font-size="11" fill="#334155">  Y grubu ise daha değişken (heterojen) yapıdadır.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Araştırma Sürecini Yeniden Planlama (MAT.7.6.1.g)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Örneklem çok küçükse (örn. yalnız 3 kişiye sorulduysa)</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  örneklem genişletilir.</text>\n  <text x="375" y="140" font-size="11" fill="#334155">• Örneklem yanlı seçildiyse (örn. okulun en sevilen</text>\n  <text x="375" y="158" font-size="11" fill="#334155">  sporu için yalnız futbol takımına sorulduysa) tüm</text>\n  <text x="375" y="176" font-size="11" fill="#334155">  şubelerden rastgele örneklem seçilir.</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Tarafsız ve Yeterli Örneklem = Doğru Karar</text>\n</svg>'}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
